#!/usr/bin/env python3
"""Soft Ecommerce Carnes Merces - configure iOS template generated by Flutter.
Runs locally; no HTTP requests, no credential changes.
Usage: python3 tooling/prepare_ios.py
"""
from pathlib import Path
import plistlib
import re
import shutil
import sys

ROOT = Path(__file__).resolve().parent.parent
IOS = ROOT / 'ios'
BUNDLE = 'br.com.softsistemas.carnesmerces'
NAME = 'Carnes Mercês'
VERSION = '15.0'
if not (IOS / 'Runner.xcodeproj/project.pbxproj').is_file():
    raise SystemExit('iOS nao existe. Rode flutter create --platforms=ios --org br.com.softsistemas --project-name soft_ecommerce_mobile .')
project = IOS / 'Runner.xcodeproj/project.pbxproj'
s = project.read_text(encoding='utf-8')
# Guarantee Runner and RunnerTests keep unique bundle identifiers.
count = 0
def rewrite(m):
    global count
    count += 1
    old = m.group(2).strip().strip('"')
    extra = '.RunnerTests' if 'RunnerTests' in old else ''
    return m.group(1) + BUNDLE + extra + ';'
s = re.sub(r'(?m)^(\s*PRODUCT_BUNDLE_IDENTIFIER\s*=\s*)([^;]+);',rewrite,s)
if count < 2:
    raise SystemExit(f'Nao foi possivel encontrar bundle identifiers no Xcode project: {count}')
s = re.sub(r'(?m)^(\s*IPHONEOS_DEPLOYMENT_TARGET\s*=\s*)([^;]+);',
           lambda m:m.group(1)+VERSION+';',s)
project.write_text(s,encoding='utf-8')

plist_file=IOS/'Runner/Info.plist'
with plist_file.open('rb') as f: info=plistlib.load(f)
info['CFBundleDisplayName']=NAME
info['CFBundleName']=NAME
info['NSLocationWhenInUseUsageDescription']='Sua localização será usada somente quando você solicitar o preenchimento aproximado do endereço de entrega.'
info['NSCameraUsageDescription']='A câmera é usada para ler códigos de barras e permitir fotos de perfil.'
info['NSPhotoLibraryUsageDescription']='Permite escolher uma foto de perfil na biblioteca do iPhone.'
info['NSFaceIDUsageDescription']='O Face ID pode proteger seu acesso à conta da loja.'
info['CFBundleLocalizations']=['pt-BR','en','es']
# Reuse secure HTTPS URL; don't weaken iOS App Transport Security.
with plist_file.open('wb') as f: plistlib.dump(info,f,sort_keys=False)

podfile=IOS/'Podfile'
if podfile.is_file():
    s=podfile.read_text(encoding='utf-8')
    # Flutter's generated Podfile may declare platform with comment.
    s=re.sub(r"(?m)^\s*#?\s*platform\s*:ios\s*,\s*['\"][^'\"]+['\"].*$", "platform :ios, '15.0'",s)
    if not re.search(r'(?m)^platform\s*:ios',s):
        s="platform :ios, '15.0'\n"+s
    podfile.write_text(s,encoding='utf-8')

# Ship our provisional test icon, not an invented official logo.
source=ROOT/'tooling/ios_branding/AppIcon.appiconset'
target=IOS/'Runner/Assets.xcassets/AppIcon.appiconset'
if not source.is_dir(): raise SystemExit('AppIcon.appiconset nao encontrado')
if target.exists(): shutil.rmtree(target)
shutil.copytree(source,target)

# Apple will sign in Codemagic using an Ad Hoc profile for the registered iPhone.
print('iOS configurado:', NAME,'|',BUNDLE,'| iOS >=',VERSION)
print('Permissions: GPS, Camera, Photos, Face ID | HTTPS required')
